import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // Restrict actor to non-zero address different from bank and from address(this)
        vm.assume(actor != address(0) && actor != c.bank() && actor != address(this));

        uint256 actorBalanceBefore = actor.balance;
        uint256 potBefore = c.pot();

        // Provide exactly TICKET_AMOUNT wei to actor and call play()
        vm.deal(actor, 10 wei);
        vm.prank(actor);
        c.play{value: 10 wei}();

        uint256 actorBalanceAfter = actor.balance;
        uint256 potAfter = c.pot();

        // Compute the random outcome that occurred inside the call
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;

        if (random == 0) {
            // Reference pays out: actor receives potBefore + 10 - 1, pot becomes 0
            assertTrue(
                actorBalanceAfter == actorBalanceBefore + potBefore + 10 wei - 1 wei &&
                potAfter == 0
            );
        } else {
            // Reference does not pay out: actor balance unchanged, pot increases by 10
            assertTrue(
                actorBalanceAfter == actorBalanceBefore &&
                potAfter == potBefore + 10 wei
            );
        }
    }
}

