pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz) public {
        // fuzz is used purely to influence the random outcome via block properties
        vm.roll(fuzz % 100000);
        address player = address(uint160(uint256(keccak256(abi.encode(fuzz)))));
        vm.assume(player != address(0) && player != address(this) && player != address(c));
        vm.deal(player, 30 ether);

        uint256 potBefore = c.pot();
        uint256 contractBalBefore = address(c).balance;

        vm.prank(player);
        c.play{value: 10}();

        uint256 potAfter = c.pot();
        uint256 contractBalAfter = address(c).balance;

        if (potAfter == 0) {
            // A payout occurred: pot reset to 0, and contract balance dropped by (potBefore + 10)
            assertTrue(contractBalAfter == contractBalBefore - potBefore - 10);
        } else {
            // No payout: pot increased by 10, and contract balance increased by 10
            assertTrue(potAfter == potBefore + 10 && contractBalAfter == contractBalBefore + 10);
        }
    }
}

