pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Keep seed in admissible domain for two plays
        uint256 seed1 = seed;
        uint256 seed2 = seed + 1;

        // Arrange for two plays by the same player with deterministic randomness that never triggers a win (random != 0)
        // We need block.timestamp, block.difficulty, and msg.sender to produce an odd random.
        // We will set timestamp and difficulty to values derived from seed that guarantee random != 0 for both plays.
        // Using seed to derive timestamp and difficulty while keeping them within realistic bounds.
        uint256 ts = bound(seed1, 1, type(uint64).max);
        uint256 diff = bound(seed2, 1, type(uint64).max);

        // Determine sender: use a random address other than the bank to avoid self-transfer interference
        address player = address(uint160(uint256(keccak256(abi.encode(seed, "player")))));
        vm.assume(player != address(0) && player != address(c) && player != address(this));

        // Ensure player has enough Ether for two tickets
        uint256 ticketAmount = 10;
        vm.deal(player, ticketAmount * 2);

        // Set block parameters so that keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender)) % 2 != 0 for both plays.
        // Since we control timestamp and difficulty, we can compute a value that yields an odd result.
        // For simplicity, we'll set them such that the hash's last bit is 1.
        // We iterate in a loop to find a timestamp/difficulty combination that gives odd for both? Instead we can just set a high timestamp and difficulty that likely work.
        // Actually, we can just warp and set difficulty, then check via internal logic? Not possible without deployment. We'll just use vm.warp and vm.difficulty with values that empirically lead to odd.
        // Safer: we'll set them to values derived from seed such that they are constant across the two calls but ensure random != 0.
        // Let's just set a high difficulty that tends to give odd for many addresses; the fuzzer will find a case if it exists.
        vm.warp(ts);
        vm.difficulty(diff);

        // First play: no win (random != 0)
        vm.prank(player);
        c.play{value: ticketAmount}();

        // Second play: same block parameters, same sender, so same random != 0
        vm.prank(player);
        c.play{value: ticketAmount}();

        // Assert: after two non-winning plays, pot should be 2 * TICKET_AMOUNT in reference, but only TICKET_AMOUNT in buggy
        assertEq(c.pot(), 2 * 10);
    }
}

