contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 seed1, uint8 seed2, uint8 blockDelta) public {
        // Constrain timestamps so block.timestamp + block.difficulty produces both win and no-win outcomes
        vm.assume(blockDelta > 0 && blockDelta < 365 days);
        // Set block difficulty so that combined with timestamp we can trigger win/loss deterministically
        vm.difficulty(1);
        // First play call
        vm.warp(1000 + seed1);
        address player1 = address(uint160(uint256(keccak256(abi.encode(seed1)))));
        vm.deal(player1, 10 ether);
        vm.prank(player1);
        c.play{value: 10}();
        bool firstWasWin = (uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, player1))) % 2 == 0);
        // Record pot after first call
        uint256 potAfterFirst = c.pot();
        // Advance block timestamp so second call uses different randomness
        vm.warp(1000 + seed1 + blockDelta);
        address player2 = address(uint160(uint256(keccak256(abi.encode(seed2)))));
        vm.deal(player2, 10 ether);
        vm.prank(player2);
