pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 difficulty, address sender) public {
        uint constant TICKET = 10;
        uint constant FEE = 1;
        vm.assume(sender != address(0));
        vm.assume(difficulty > 0);
        vm.warp(timestamp);
        vm.roll(difficulty);
        // First play: force a win by manipulating the hash input so that random == 0
        // We can't control block.timestamp/difficulty after warp/roll, so we just try many times;
        // but we need a guaranteed win pattern. Instead play twice where first is a win, second is not.
        // Use bound to keep values reasonable.

        // Deal and prank
        vm.deal(sender, TICKET * 2);
        vm.startPrank(sender);

        // First play. We want a win. Calculate if random would be 0. We can't use vm.difficulty, but we can
        // rely on the fuzzer finding values where the first play wins. We just call play().
        (bool ok1, ) = address(c).call{value: TICKET}(abi.encodeWithSignature("play()"));
        require(ok1, "first play failed");

        // If pot is 0, we had a win. If not, we skip this run (assume we had a win).
        vm.assume(c.pot() == 0);

        // Now second play. Use a different sender or modify environment to get random != 0.
        // We can change block.timestamp slightly.
        vm.warp(timestamp + 100);
        // Deal again if sender balance drained, but we already have enough.
        (bool ok2, ) = address(c).call{value: TICKET}(abi.encodeWithSignature("play()"));
        require(ok2, "second play failed");

        vm.stopPrank();

        // After a win resets pot to 0, and a second play deposits TICKET,
        // reference pot == TICKET, buggy pot == TICKET. BUT: if the second play also wins?
        // To see difference, we need second play to LOSE, so pot remains.
        // We assume second play loses (pot > 0). If it wins again, pot = 0 both, no diff.
        // So assume pot > 0 after second play.
        vm.assume(c.pot() > 0);

        // The invariant: after a win empties pot and a subsequent play that does NOT win,
        // the reference pot should be exactly TICKET (accumulated from the play).
        // The buggy pot is also TICKET because it just overwrites, but wait:
        // After a win, reference pot = 0. After second play (lose), reference pot += TICKET => TICKET.
        // Buggy after win: pot = msg.value = TICKET; after second play: pot = msg.value = TICKET.
        // This specific sequence doesn't differ. Need sequence where accumulation matters.

        // Instead: two consecutive losing plays, then a winning play.
        // Reference: pot = 2*TICKET before win, win pays out bank fee + (2*TICKET - FEE) to sender, pot=0.
        // Buggy: pot = TICKET before win, win pays out bank fee + (TICKET - FEE) to sender, pot=0.
        // After win, both have pot=0. But the buggy sent less to sender if TICKET < 2*TICKET - FEE.
        // However, our assertion must read from c, e.g., pot after sequence.
        // Better: compare pot after a sequence ending with a losing play.
        // Let's do: play, play (both lose), pot differs.

        // Restart with new state.
        c = new C();
        vm.deal(sender, TICKET * 3);
        vm.startPrank(sender);
        vm.warp(timestamp);
        vm.roll(difficulty);
        // First play lose
        vm.assume(uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, sender))) % 2 != 0);
        c.play{value: TICKET}();
        // Second play lose
        vm.assume(uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, sender))) % 2 != 0);
        c.play{value: TICKET}();
        vm.stopPrank();

        // Reference pot == 2*TICKET, buggy == TICKET.
        assertTrue(c.pot() == 2*TICKET);
    }
}

