contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // The fuzzer provides a random seed to influence block.timestamp and block.difficulty.
        // We warp to spread out timestamps and choose difficulty via seed.
        vm.warp(1000 + (seed % 100000));
        vm.roll(uint256(keccak256(abi.encode(seed))) % 10_000_000 + 1);

        // Admissible: play requires exactly TICKET_AMOUNT (10 wei).
        uint256 ticket = 10;
        address player = address(0x1234);
        vm.deal(player, ticket);

        // Record state before play
        uint256 bankBalBefore = c.bank().balance;
        uint256 potBefore = c.pot();
        uint256 cBalBefore = address(c).balance;
        bool isWin;
        {
            vm.prank(player);
            // We need to know if this specific call results in a win.
            // We simulate: the outcome depends on block.timestamp, block.difficulty, and msg.sender.
            uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, player))) % 2;
            isWin = (random == 0);
            c.play{value: ticket}();
        }

        // After play
        uint256 cBalAfter = address(c).balance;
        uint256 potAfter = c.pot();
        uint256 bankBalAfter = c.bank().balance;

        // In the correct contract, after a win:
        // - pot becomes 0
        // - bank receives 1 wei (FEE_AMOUNT) from the contract's balance (via transfer)
        // - player receives potBefore + ticket - 1 wei
        // - total balance (c + bank) after = total deposited (cBalBefore + ticket) - 1 wei
