        uint256 totalAfter = cBalAfter + bankBalAfter;

        if (isWin) {
            // Correct: totalAfter == totalDeposited - 1
            // Buggy: totalAfter == totalDeposited (because fee wasn't deducted from payout)
            assertTrue(totalAfter == totalDeposited - 1);
        } else {
            // Loss: pot just accumulates ticket, no payout.
            // Total balance unchanged: cBalBefore + ticket == cBalAfter + bankBalAfter
            assertTrue(totalAfter == totalDeposited);
        }
